import { buildConnectorGraph } from "./connectors.js";
import { axialToPixel, getGridBounds } from "./hex.js";
import { resolveTopologyIcon } from "./topologyIconRegistry.js";
function escapeMarkup(value) {
    return String(value)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
}
function imageClipId(node) {
    return `occupant-image-clip-${node.id.replace(/[^a-zA-Z0-9_-]/g, "-")}-${node.q}-${node.r}`;
}
function occupantWithCell(node, cellMap) {
    const cell = cellMap.get(node.cellId);
    return cell ? { ...node, cell } : null;
}
export function renderTopologyGridMarkup({ frame, radius, activeCellIds = [], cellStates = {}, showNodes = true, className = "", connectorRouting = "straight", }) {
    const { cells } = frame;
    const bounds = getGridBounds(cells, radius);
    const cellMap = new Map(cells.map((cell) => [cell.id, cell]));
    const activeSet = new Set(activeCellIds);
    const occupiedEntries = frame.occupants
        .map((node) => occupantWithCell(node, cellMap))
        .filter((node) => Boolean(node));
    const transitionOrder = new Map(occupiedEntries.map((node, index) => [node.id, index]));
    const gridOffset = cells[0]
        ? {
            x: cells[0].center.x - axialToPixel(cells[0], radius).x,
            y: cells[0].center.y - axialToPixel(cells[0], radius).y,
        }
        : { x: 0, y: 0 };
    const connectorGraph = buildConnectorGraph(occupiedEntries, frame.relationships, radius, gridOffset, {
        routingMode: connectorRouting,
        cells,
    });
    const imageClips = occupiedEntries
        .filter((node) => typeof node.image === "string" && node.image.length > 0)
        .map((node) => `
      <clipPath id="${imageClipId(node)}"><path d="${escapeMarkup(node.cell.path)}" /></clipPath>`)
        .join("");
    const connectorMarkup = connectorGraph.routes.map((edge) => `
    <path
      class="grid-connector${edge.connectorState === "active" ? " connector-state-active" : ""}${edge.connectorState === "related" ? " connector-state-related" : ""}${edge.connectorState === "disabled" ? " connector-state-disabled" : ""}"
      d="${escapeMarkup(edge.d)}"
      data-edge-from="${escapeMarkup(edge.from)}"
      data-edge-to="${escapeMarkup(edge.to)}"
      data-topology-transition-kind="connector"
      data-topology-transition-order="${transitionOrder.get(edge.to) ?? 0}"
      data-connector-state="${edge.connectorState}"
      data-edge-signal-state="${edge.connectorState === "active" ? "propagating" : edge.connectorState === "related" ? "receiving" : "idle"}"
      data-routing-mode="${edge.routingMode}"
      data-routing-status="${edge.routingStatus}"
      data-from-socket="${edge.startDirection ?? ""}"
      data-to-socket="${edge.endDirection ?? ""}"
    />`).join("");
    const lines = cells.map((cell) => {
        const state = cellStates[cell.id];
        const isActive = state ? state.state === "active" : activeSet.has(cell.id);
        const isTrail = state?.state === "trail";
        const isConverted = state?.state === "converted";
        const isTileAlt = ((cell.q + cell.r) & 1) !== 0;
        const intensity = state?.intensity ?? (isActive ? 1 : activeSet.has(cell.id) ? 0.7 : 0.24);
        const edgeFactor = cell.edgeFactor ?? 1;
        const stateName = state?.state ?? (isActive ? "active" : "idle");
        return `
      ${isActive || isTrail || isConverted ? `
      <path
        class="grid-hex-signal${isActive ? " is-active" : ""}${isTrail ? " is-trail" : ""}${isConverted ? " is-converted" : ""}"
        d="${escapeMarkup(cell.path)}"
        data-cell-id="${escapeMarkup(cell.id)}"
        data-q="${cell.q}"
        data-r="${cell.r}"
        data-cell-state="${stateName}"
        style="--cell-intensity:${intensity}; --cell-edge-factor:${edgeFactor};"
      />` : ""}
      <path
        id="${escapeMarkup(cell.id)}"
        class="grid-hex${isTileAlt ? " is-tile-alt" : ""}${isActive ? " is-active" : ""}${isTrail ? " is-trail" : ""}${isConverted ? " is-converted" : ""}"
        d="${escapeMarkup(cell.path)}"
        data-cell-id="${escapeMarkup(cell.id)}"
        data-q="${cell.q}"
        data-r="${cell.r}"
        data-cx="${cell.center.x}"
        data-cy="${cell.center.y}"
        data-cell-state="${stateName}"
        style="--cell-intensity:${intensity}; --cell-edge-factor:${edgeFactor};"
      />`;
    }).join("");
    const nodes = showNodes
        ? cells.map((cell) => {
            const state = cellStates[cell.id];
            const isActive = state ? state.state === "active" : activeSet.has(cell.id);
            const isTrail = state?.state === "trail";
            const isConverted = state?.state === "converted";
            const intensity = state?.intensity ?? (isActive ? 1 : activeSet.has(cell.id) ? 0.7 : 0.24);
            const edgeFactor = cell.edgeFactor ?? 1;
            const stateName = state?.state ?? (isActive ? "active" : "idle");
            return `
          ${isActive || isTrail || isConverted ? `
          <circle
            class="grid-node-signal${isActive ? " is-active" : ""}${isTrail ? " is-trail" : ""}${isConverted ? " is-converted" : ""}"
            cx="${cell.center.x}"
            cy="${cell.center.y}"
            r="${Math.max(2.5, radius * 0.18)}"
            data-cell-id="${escapeMarkup(cell.id)}"
            data-q="${cell.q}"
            data-r="${cell.r}"
            data-cell-state="${stateName}"
            style="--cell-intensity:${intensity}; --cell-edge-factor:${edgeFactor};"
          />` : ""}
          <circle
            class="grid-node${isActive ? " is-active" : ""}${isTrail ? " is-trail" : ""}${isConverted ? " is-converted" : ""}"
            cx="${cell.center.x}"
            cy="${cell.center.y}"
            r="${Math.max(1, radius * 0.055)}"
            data-cell-id="${escapeMarkup(cell.id)}"
            data-q="${cell.q}"
            data-r="${cell.r}"
            data-cell-state="${stateName}"
            style="--cell-intensity:${intensity}; --cell-edge-factor:${edgeFactor};"
          />`;
        }).join("")
        : "";
    const occupants = occupiedEntries.map((node, nodeIndex) => {
        const size = node.size ?? "md";
        const isDisabled = Boolean(node.disabled);
        const isActive = Boolean(node.active);
        const isSelected = Boolean(node.selected);
        const icon = resolveTopologyIcon(node.icon);
        const labelSize = Math.max(12, radius * 0.26);
        const subtitleSize = Math.max(8, radius * 0.13);
        const titleOffset = node.subtitle ? Math.max(4, radius * 0.08) : Math.max(2, radius * 0.04);
        const subtitleOffset = Math.max(12, radius * 0.24);
        const imageSource = node.image ?? icon?.image;
        const imageScale = Math.max(0.1, Number(node.imageScale ?? icon?.imageScale ?? 1));
        const imageAlign = node.imageAlign ?? icon?.imageAlign ?? "center";
        const imageWidth = Math.sqrt(3) * radius * imageScale;
        const imageHeight = radius * 2 * imageScale;
        const imageOffsetY = Number(node.imageOffsetY ?? 0) * radius;
        const imageX = node.cell.center.x - imageWidth / 2;
        const imageY = imageAlign === "top"
            ? node.cell.center.y - radius + radius * 0.12 + imageOffsetY
            : node.cell.center.y - imageHeight / 2 + imageOffsetY;
        const ariaLabel = node.subtitle ? `${node.label}. ${node.subtitle}` : node.label;
        return `
      <g
        class="grid-occupant variant-${escapeMarkup(node.variant ?? "secondary")} size-${escapeMarkup(size)}${isActive ? " is-active" : ""}${isSelected ? " is-selected" : ""}${isDisabled ? " is-disabled" : ""}"
        data-node-id="${escapeMarkup(node.id)}"
        data-q="${node.q}"
        data-r="${node.r}"
        data-cell-id="${escapeMarkup(node.cell.id)}"
        data-node-state="${isSelected ? "selected" : isActive ? "active" : "idle"}"
        data-topology-transition-depth="${node.variant === "root" ? 0 : node.variant === "anchor" ? 1 : 2}"
        data-topology-transition-order="${nodeIndex}"
        data-topology-transition-kind="node"
        aria-label="${escapeMarkup(ariaLabel)}"
        aria-current="${isSelected || isActive ? "true" : "false"}"
        aria-disabled="${isDisabled ? "true" : "false"}"
        role="button"
        tabindex="${isDisabled ? "-1" : "0"}"
        style="--occupant-title-size:${labelSize}px; --occupant-subtitle-size:${subtitleSize}px; --cell-edge-factor:${node.cell.edgeFactor ?? 1};"
      >
        <path class="grid-occupant-fill" d="${escapeMarkup(node.cell.path)}" />
        ${imageSource ? `<image class="grid-occupant-image" href="${escapeMarkup(imageSource)}" x="${imageX}" y="${imageY}" width="${imageWidth}" height="${imageHeight}" preserveAspectRatio="xMidYMid meet" clip-path="url(#${imageClipId(node)})" />` : ""}
        <text class="grid-occupant-label" x="${node.cell.center.x}" y="${node.cell.center.y - titleOffset}" text-anchor="middle">${escapeMarkup(node.label)}</text>
        ${node.subtitle ? `<text class="grid-occupant-subtitle" x="${node.cell.center.x}" y="${node.cell.center.y + subtitleOffset}" text-anchor="middle">${escapeMarkup(node.subtitle)}</text>` : ""}
      </g>`;
    }).join("");
    const hasOccupants = occupiedEntries.length > 0;
    return `
    <svg class="topology-grid${className ? ` ${escapeMarkup(className)}` : ""}" data-radius="${radius}" viewBox="${bounds.minX} ${bounds.minY} ${bounds.width} ${bounds.height}" ${hasOccupants ? 'aria-label="Operational topology" role="group"' : 'aria-hidden="true" role="presentation"'} focusable="false">
      ${imageClips ? `<defs>${imageClips}</defs>` : ""}
      <g class="grid-lines" aria-hidden="true">${lines}</g>
      ${connectorMarkup ? `<g class="grid-connectors" aria-hidden="true">${connectorMarkup}</g>` : ""}
      ${showNodes ? `<g class="grid-nodes" aria-hidden="true">${nodes}</g>` : ""}
      <g class="grid-occupants">${occupants}</g>
    </svg>
  `;
}
